CREATE VIEW std_wiiu_inventory AS SELECT main."trim"(Title) AS game_title, "Game Genre" AS genre_raw, Theme AS theme_raw, "Mode" AS mode_raw, Perspective AS perspective_raw, "nullif"(main."trim"("Source"), 'N/A') AS acquisition_source_raw, NULL AS storage_location_raw, "nullif"(main."trim"(Folder), 'N/A') AS organization_folder_raw, "nullif"(main."trim"(Status), 'N/A') AS play_status_raw, CASE  WHEN ((main."trim"(CAST("Owned" AS VARCHAR)) = 'Y')) THEN (CAST('t' AS BOOLEAN)) WHEN ((main."trim"(CAST("Owned" AS VARCHAR)) = 'N')) THEN (CAST('f' AS BOOLEAN)) ELSE NULL END AS owned_flag, TRY_CAST("nullif"("Difficulty (out of 5)", 'N/A') AS DECIMAL(3,2)) AS difficulty_rating, TRY_CAST("nullif"("Game Length (in hours)", 'N/A') AS DECIMAL(8,2)) AS full_completion_hours, TRY_CAST("nullif"("File Size (in GB)", 'N/A') AS DECIMAL(10,2)) AS file_size_gb, 'Wii U' AS platform_name FROM stg_wiiu_inventory;
